starterCode.python:
class Codec:
    def serialize(self, root):
        res = []
        def dfs(node):
            if not node: res.append('N'); return
            res.append(str(node.val))
            dfs(node.left); dfs(node.right)
        dfs(root)
        return ','.join(res)
    def deserialize(self, data):
        nodes = data.split(',')
        self.i = 0
        def dfs():
            if nodes[self.i] == 'N': self.i += 1; return None
            node = TreeNode(int(nodes[self.i]))
            self.i += 1
            node.left = dfs(); node.right = dfs()
